create table if not exists owners(id uuid primary key default gen_random_uuid(),email text unique not null,password_hash text not null,created_at timestamptz default now());
create table if not exists customers(id uuid primary key default gen_random_uuid(),name text,email text,phone text not null,created_at timestamptz default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),name text not null,description text default '',category text not null check(category in('gold','silver','diamond','other')),purity text,weight_grams numeric(10,3),price_paise integer not null check(price_paise>=0),availability boolean default true,sku text unique not null,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists product_images(id uuid primary key default gen_random_uuid(),product_id uuid references products(id) on delete cascade not null,storage_path text not null,position int default 0);
create table if not exists product_videos(id uuid primary key default gen_random_uuid(),product_id uuid references products(id) on delete cascade not null,storage_path text not null,position int default 0);
create table if not exists collections(id uuid primary key default gen_random_uuid(),title text not null,description text default '',published boolean default false,position int default 0,created_at timestamptz default now());
create table if not exists collection_media(id uuid primary key default gen_random_uuid(),collection_id uuid references collections(id) on delete cascade not null,storage_path text not null,media_type text check(media_type in('image','video')) not null,position int default 0);
create table if not exists orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,customer_id uuid references customers(id),subtotal_paise int not null,delivery_paise int default 0,tax_paise int default 0,total_paise int not null,payment_status text default 'pending_verification' check(payment_status in('pending_verification','paid','failed','cancelled')),order_status text default 'awaiting_payment' check(order_status in('awaiting_payment','processing','shipped','delivered','cancelled')),created_at timestamptz default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,product_id uuid references products(id),product_name text not null,sku text,unit_price_paise int not null,quantity int not null check(quantity>0),line_total_paise int not null);
create table if not exists payments(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id) on delete cascade,method text default 'upi',upi_transaction_ref text,payment_claimed_at timestamptz,verified_at timestamptz,verified_by uuid references owners(id),created_at timestamptz default now());
create table if not exists messages(id uuid primary key default gen_random_uuid(),name text not null,email text not null,phone text,message text not null,created_at timestamptz default now());
create table if not exists metal_rates(id uuid primary key default gen_random_uuid(),metal text unique not null,rate_paise integer not null,last_updated timestamptz not null default now(),source text not null default 'Owner managed');
create table if not exists site_settings(key text primary key,value jsonb not null,updated_at timestamptz default now());
insert into metal_rates(metal,rate_paise,source) values('Gold 24K',0,'Not set'),('Gold 22K',0,'Not set'),('Gold 916',0,'Not set'),('Gold 18K',0,'Not set'),('Silver',0,'Not set'),('Diamond',0,'Not set') on conflict(metal) do nothing;